/* 场景化清空, 推荐配合重载 */

/* 1) 软清空: 保留相机/光源, 只清模型 */
ssp.sceneTool.clear(true);

/* 2) 硬清空: 连相机/光源也清 (场景会变黑) */
ssp.sceneTool.clear(false);

/* 3) 切换场景: clear + loadSubcategory */
ssp.sceneTool.clear();
const infos = await ssp.modelTool.loadSubcategory('hospital');
console.log('loaded', infos.length, 'GLB');
